package com.ragpipeline.service;
import com.ragpipeline.model.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.util.*;
@Service @RequiredArgsConstructor public class CitationVerificationService {private final BgeRerankerService reranker;public List<Citation> verify(String answer,List<Citation> citations,List<RetrievedChunk> chunks){return citations.stream().map(c->{RetrievedChunk x=chunks.stream().filter(z->Objects.equals(z.getChunkId(),c.getChunkId())).findFirst().orElse(null);double score=x==null?0:reranker.scorePair(claim(answer,c.getIndex()),x.getContent());c.setVerificationScore(score);c.setVerified(score>=.4);return c;}).toList();}private String claim(String a,int i){int p=a.indexOf("["+i+"]");return p<0?a.substring(0,Math.min(200,a.length())):a.substring(Math.max(0,p-100),Math.min(a.length(),p+103));}}
